/// Return the syscall number named `name` for `arch`, or `None` if that architecture has no such syscall.
pub fn number(arch: Arch, name: &str) -> Option<u32> {
    let table = match arch {
        Arch::X86_64 => X86_64,
        Arch::Aarch64 => AARCH64,
        Arch::Riscv64 => RISCV64,
    };
    table
        .binary_search_by(|(candidate, _)| (*candidate).cmp(name))
        .ok()
        .map(|index| table[index].1)
}

/// Return the syscall name for `number` on `arch`, or `None` if that architecture has no such number.
pub fn name(arch: Arch, number: u32) -> Option<&'static str> {
    let table = match arch {
        Arch::X86_64 => X86_64_BY_NR,
        Arch::Aarch64 => AARCH64_BY_NR,
        Arch::Riscv64 => RISCV64_BY_NR,
    };
    table
        .binary_search_by_key(&number, |&(_, candidate)| candidate)
        .ok()
        .map(|index| table[index].0)
}
